#!/usr/bin/env bash
# Generated by Capsules (template 1.2.0).
# Runs on every start of the environment (postAttachCommand). The Dev Container
# CLI runs post-create.sh once per container and never again, even when it
# failed, for example when the network dropped during npm install. This script
# checks the install marker. When it is missing or names other versions than
# agent-versions.sh, it runs post-create.sh again and fails when that fails, so
# the start reports the error instead of looking healthy. It never installs
# anything newer than the pinned versions.
set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=agent-versions.sh
. "$script_dir/agent-versions.sh"

if [ -f "$AGENTS_MARKER" ] && [ "$(cat "$AGENTS_MARKER")" = "$(expected_agents_marker)" ]; then
  exit 0
fi

echo "agents: the pinned agent CLIs are not fully installed in this container; installing them now"
bash "$script_dir/post-create.sh"
